function combinationSum(candidates: number[], target: number): number[][] {
  // Сортировка позволяет прервать цикл, как только число стало больше остатка
  const sorted = [...candidates].sort((a, b) => a - b);
  const result: number[][] = [];
  const path: number[] = [];

  // start — с какого кандидата можно продолжать (чтобы не было перестановок одной комбинации)
  // remain — сколько ещё осталось набрать
  const backtrack = (start: number, remain: number): void => {
    if (remain === 0) {
      // Сумма набрана точно — сохраняем копию
      result.push([...path]);
      return;
    }

    for (let i = start; i < sorted.length; i++) {
      // Дальше числа только больше — ни одно уже не поместится
      if (sorted[i] > remain) break;

      path.push(sorted[i]);
      // Передаём i, а не i + 1: то же число можно взять ещё раз
      backtrack(i, remain - sorted[i]);
      path.pop(); // откат
    }
  };

  backtrack(0, target);
  return result;
}

// Время: O(N^(T/M + 1)) в худшем случае: N — число кандидатов, T — target, M — минимальный кандидат
// Память: O(T/M) — максимальная глубина рекурсии (без учёта ответа)
